new='''class PrefixHopMap {
public:
    void build(const std::vector<IPPrefix>& prefixes) {
        map_.clear();
        map_.reserve(prefixes.size() * 2 + 1);
        for (const IPPrefix& p : prefixes) {
            PrefixKey key{p.length, p.address.hi, p.address.lo};
            map_[key] = p.hop;
        }
    }

    bool lookup(unsigned length, const ip6_t& masked_address,
                uint32_t& hop) const {
        PrefixKey key{static_cast<uint8_t>(length), masked_address.hi,
                      masked_address.lo};
        auto it = map_.find(key);
        if (it == map_.end()) return false;
        hop = it->second;
        return true;
    }

private:
    std::unordered_map<PrefixKey, uint32_t, PrefixKeyHash> map_;
};
'''
